import {realismFor,REALISM_PRESETS,materialPrice} from './realism.js';
import {filamentStock,stockNeeds,colorFor,printers,presence,metrics} from './model.js';
import {goodsFor} from './creations.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>(Number(n)||0).toLocaleString('fr-FR',{maximumFractionDigits:d});
const euro=n=>(Number(n)||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2});
export function compactStock(s,basket){const missing=stockNeeds(s).filter(n=>n.missing>0),lots=new Map();for(const l of s.inventory){const key=l.material+':'+l.colorId;if(!lots.has(key))lots.set(key,{...l});else lots.get(key).grams+=l.grams;}return `<div class="stock-rail-title"><span>Filaments</span><b>${num((s.stock.pla+s.stock.petg)/1000,2)} kg</b></div><div class="stock-rail-colors" data-scroll-key="filaments">${[...lots.values()].map(l=>`<button data-action="stock-color" data-material="${l.material}" data-color="${l.colorId==='legacy'?'natural':l.colorId}" title="${l.material.toUpperCase()} ${colorFor(l.colorId).name} : ${num(l.grams)} g"><i style="background:${colorFor(l.colorId).hex}"></i><span>${l.material.toUpperCase()}<b>${num(l.grams)} g</b></span></button>`).join('')||'<span class="stock-rail-empty">Stock vide</span>'}</div><button class="stock-rail-add" data-action="quick-stock" aria-label="Voir le stock et acheter des bobines">＋<span>Stock</span></button>${missing.length?`<button class="stock-rail-alert" data-action="restock-needed">${missing.length} couleur(s) manquante(s) →</button>`:''}<div class="stock-rail-extras"><button data-action="creations-panel">${goodsFor(s)} objet(s) prêt(s)</button><button data-action="energy">ϟ ${euro(s.energy.unbilledCost)} en cours</button>${basket.length?'<span>Panier préparé</span>':''}</div>`;}
export function atelierPulse(s){const p=presence(s),machines=printers(s),m=metrics(s),missing=stockNeeds(s).filter(n=>n.missing>0),title=p.kind==='sleep'?'Ton artisan dort':p.kind==='away'?'Ton artisan est au travail':p.kind==='remote'?'Télétravail':p.canWork?s.worker?s.worker.label:'Un créneau disponible':'Temps libre',detail=p.canWork&&s.worker?num(Math.max(0,s.worker.remaining))+' min de travail restantes':machines.some(v=>v.job)?'Les impressions lancées continuent.':p.canWork?'Choisis un projet ou laisse les consignes prendre le relais.':'Les tâches manuelles attendent le prochain créneau.',progress=p.canWork&&s.worker?Math.max(0,Math.min(100,100*(1-s.worker.remaining/s.worker.total))):null;let action='';if(!machines.length)action='<button data-action="nav" data-view="build">Installer une machine →</button>';else if(missing.length)action='<button data-action="restock-needed">Prévoir le filament →</button>';else if(m.requests)action='<button data-action="nav" data-view="orders">'+m.requests+' demande(s) →</button>';else if(!s.worker&&p.canWork)action='<button data-action="creations-panel">Créer un objet →</button>';return `<span class="pulse-symbol">${p.kind==='sleep'?'☾':p.kind==='away'?'⌂':s.worker?'↻':'✦'}</span><div><b>${esc(title)}</b><span>${esc(detail)}</span>${progress!==null?`<div class="worker-progress"><i style="width:${progress}%"></i></div>`:''}</div>${action}`;}
export function automationBar(s){const active=s.settings.autoAccept&&s.settings.autoShip&&s.settings.autoRestock;return `<button class="idle-main ${active?'enabled':''}" data-action="idle-preset" aria-pressed="${active}" title="Confirmer, réapprovisionner, expédier et entretenir selon tes horaires"><i></i><span>${active?'Auto actif':'Activer l’auto'}</span></button><button data-action="pilot-panel" class="idle-instructions" title="Choisir les automatismes et les temps creux">Consignes</button>`;}
export function timeControls(speed,lastSpeed){const selected=speed||lastSpeed;return `<button class="time-play" data-action="pause" aria-label="${speed?'Mettre en pause':'Reprendre'}">${speed?'Ⅱ':'▶'}</button><label class="speed-choice"><span>Vitesse</span><select data-speed-choice aria-label="Vitesse du temps simulé">${[60,240,480,1440,7200].map(v=>`<option value="${v}" ${selected===v?'selected':''}>1 min = ${v/60} h${v===240?' · doux':''}</option>`).join('')}</select></label><button data-action="skip" class="skip-time" aria-label="Avancer jusqu’à la prochaine étape de la journée" title="Prochaine étape">↷</button>`;}
export function settingsTabs(active){return `<nav class="settings-tabs" aria-label="Catégories de réglages">${[['realism','Réalisme'],['life','Horaires'],['sounds','Sons'],['saves','Sauvegardes']].map(([id,label])=>`<button data-action="settings-tab" data-tab="${id}" aria-pressed="${active===id}">${label}</button>`).join('')}</nav>`;}
const field=(key,label,value,min,max,step=1,unit='',note='')=>`<label class="realism-field"><span>${label}${note?`<small>${note}</small>`:''}</span><span><input name="${key}" value="${value}" type="number" min="${min}" max="${max}" step="${step}" required>${unit?`<em>${unit}</em>`:''}</span></label>`;
export function realismForm(s){const r=realismFor(s),mode=s.settings.presentation?.animation||'fluid';return `<form id="realism-form"><p class="settings-lead">Choisis un profil ou ajuste quelques hypothèses. Les changements concernent la suite de la partie ; les bobines et livraisons déjà payées gardent leur coût.</p><div class="realism-presets">${Object.entries(REALISM_PRESETS).map(([id,p])=>`<button type="button" data-action="realism-preset" data-id="${id}" title="${p.note}"><b>${p.name}</b><span>${p.note}</span></button>`).join('')}</div><details class="realism-group" open><summary>Marché et charges</summary>${field('demand','Niveau de demande',r.demand,.4,1.6,.1,'×','1 = marché de référence ; la clientèle reste limitée.')}${field('monthlyFixed','Frais fixes',r.monthlyFixed,0,1500,5,'€/mois','Assurance, logiciels et fonctionnement.')}${field('hourValue','Valeur de ton temps',r.hourValue,0,60,1,'€/h','Pour estimer le résultat après travail personnel.')}${field('electricity','Tarif électrique',s.settings.electricity,.05,2,.01,'€/kWh')}${field('taxRate','Provision sociale et fiscale',s.settings.taxRate,0,60,.5,'%','Hypothèse simplifiée du jeu.')}</details><details class="realism-group"><summary>Matières et livraisons</summary>${field('plaPrice','PLA · nouvelle bobine',r.plaPrice,10,80,1,'€/kg')}${field('petgPrice','PETG · nouvelle bobine',r.petgPrice,12,90,1,'€/kg')}${field('supplierShipping','Port fournisseur groupé',r.supplierShipping,0,20,.1,'€')}${field('supplierHours','Préparation fournisseur',r.supplierHours,8,120,4,'h','Puis réception au prochain créneau ouvré à 10 h.')}</details><details class="realism-group"><summary>Fiabilité et consommation</summary>${field('failureRate','Risques de panne et de raté',r.failureRate,.5,2,.1,'×')}${field('maintenanceHours','Entretien préventif après',r.maintenanceHours,80,400,10,'h')}${field('amortizationYears','Amortissement des nouveaux achats',r.amortizationYears,3,10,1,'ans','Ce n’est pas une date de destruction de la machine.')}${field('standbyW','Veille par imprimante',r.standbyW,0,20,1,'W','0 pour compter seulement les impressions.')}${field('auxiliaryW','Bureau et éclairage pendant la présence',r.auxiliaryW,0,200,5,'W')}</details><details class="realism-group"><summary>Trésorerie et confort de jeu</summary>${field('reserve','Réserve minimale',s.settings.reserve,0,100000,10,'€')}${field('monthlyDraw','Objectif de retrait personnel',s.settings.monthlyDraw,0,10000,50,'€/mois')}<label class="realism-field"><span>Animations<small>La vitesse économique reste identique dans les trois modes.</small></span><select name="animation"><option value="fluid" ${mode==='fluid'?'selected':''}>Fluides · 30 i/s</option><option value="eco" ${mode==='eco'?'selected':''}>Économie · 20 i/s</option><option value="instant" ${mode==='instant'?'selected':''}>Directes</option></select></label></details><p id="realism-error" role="status"></p><div class="settings-submit"><span>Hypothèses de simulation, à adapter à tes coûts.</span><button type="submit" class="button primary">Appliquer les réglages</button></div></form>`;}
export function savesPanel(){return `<div class="save-actions"><p>La partie se sauvegarde automatiquement sur cet appareil. Un export permet de la conserver ou de la transférer.</p><button class="button primary" data-action="save">Sauvegarder maintenant</button><button class="button secondary" data-action="export">Exporter ma partie</button><button class="button secondary" data-action="import">Importer une sauvegarde</button><button class="button secondary" data-action="nav" data-view="journal">Voir le journal de l’atelier</button><button class="button secondary" data-action="guide">Aide et règles du jeu</button><details class="realism-group"><summary>Recommencer ou restaurer</summary><button class="text-button danger" data-action="reset-confirm">Nouvelle partie · 1 500 €</button><button class="text-button" data-action="restore">Restaurer la copie avant reset</button></details></div>`;}
